package com.game_manager.gm.workflow; import com.game_manager.gm.common.entity.BaseEntity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="workflow_definition_versions") @Getter @Setter @NoArgsConstructor public class WorkflowDefinitionVersion extends BaseEntity {@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="definition_id",nullable=false)private WorkflowDefinition definition;@Column(name="version_number",nullable=false)private int versionNumber;@Column(name="schema_json",nullable=false,columnDefinition="TEXT")private String schemaJson;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="published_by",nullable=false,length=36)private UUID publishedBy;@Column(name="published_at",nullable=false)private Instant publishedAt;}
